## Frontend Guidelines

### Component Structure

Components follow a consistent structure:

```typescript
// 1. Imports
import { Component } from "library";
import { useStore } from "@/hooks/useStore";

input.command:
python3 - <<'EOF'
import re, os
files = [f for f in os.listdir('.') if f.endswith('.py') and f != '__init__.py']
edges = {}
for f in files:
    mod = f[:-3]
    src = open(f).read()
    deps = set()
    for m in re.finditer(r'from app\.services\.([a-zA-Z0-9_]+) import', src):
        deps.add(m.group(1))
    for m in re.finditer(r'from app\.services import ([a-zA-Z0-9_, ]+)', src):
        for name in m.group(1).split(','):
            name = name.strip()
            if name and (name + '.py') in files:
                deps.add(name)
    for m in re.finditer(r'import app\.services\.([a-zA-Z0-9_]+)', src):
        deps.add(m.group(1))
    deps.discard(mod)
    if deps:
        edges[mod] = sorted(deps)
for mod in sorted(edges):
    print(f"{mod}: {', '.join(edges[mod])}")
EOF
